import React from 'react';
import ReactDOM from 'react-dom/client';
import store from './store';
import { Provider } from 'react-redux';
import Chat, { ChatProps } from './components/Chat';
import './index.css';
import './i18n/config';

declare global {
  interface Window {
    ChatWidgetConfig?: Partial<ChatProps>;
    ChatWidget?: {
      initChat: (el: HTMLElement, opts: ChatProps) => void;
      updateChat: (el: HTMLElement, opts: Partial<ChatProps>) => void;
    };
  }
}

function parseAttributes(el: HTMLElement): Partial<ChatProps> {
  return {
    apiKey: el.dataset.apikey,
    baseUrl: el.dataset.baseurl
  };
}

function renderChat(el: HTMLElement, opts: ChatProps) {
  ReactDOM.createRoot(el).render(
    <React.StrictMode>
      <Provider store={store}>
        <Chat {...opts} />
      </Provider>
    </React.StrictMode>
  );
}

function initAll() {
  const globalConfig = window.ChatWidgetConfig || {};
  document.querySelectorAll<HTMLElement>('[data-chatroom]').forEach(el => {
    const attr = parseAttributes(el);
    const opts = { ...globalConfig, ...attr } as ChatProps;
    renderChat(el, opts);
  });
}

export function initChat(el: HTMLElement, opts: ChatProps) {
  renderChat(el, opts);
}

export function updateChat(el: HTMLElement, newOpts: Partial<ChatProps>) {
  const event = new CustomEvent('chat:updateOpts', { detail: newOpts });
  el.dispatchEvent(event);
}

function setupGlobalListener() {
  window.addEventListener('ChatWidget:updateGlobal', e => {
    const { containerSelector, opts } = (e as CustomEvent).detail;
    const el = document.querySelector<HTMLElement>(containerSelector);
    if (el) updateChat(el, opts);
  });
}

if (typeof window !== 'undefined') {
  window.ChatWidget = {
    initChat,
    updateChat,
  };

  if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', () => {
      initAll();
      setupGlobalListener();
    });
  } else {
    initAll();
    setupGlobalListener();
  }
}