import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import {
  getSkillInfo,
  uploadFile,
  deletePersonalFile,
  setFeedback
} from '@/api/chatApi';

type Skill = {
  collections: Array<string>;
  description: string;
  modelName: string;
  skillName: string;
  skillID: string;
  taskName: string;
}

export const getSkillInfoAction = createAsyncThunk('appChat/fetchTaskList', async (payload: { apiKey: string, baseUrl: string }) => {
  try {
    const res = await getSkillInfo(payload.baseUrl, payload.apiKey);
    return res.data;
  }
  catch (error) {
    return error;
  }
})

export const uploadFileAction = createAsyncThunk('appChat/uploadFile', async (payload: { chatID?: string, skillID: string, files: File[], baseUrl: string; }) => {
  try {
    const data = {
      chatID: payload.chatID,
      skillID: payload.skillID,
      files: payload.files
    }
    const res = await uploadFile(data, payload.baseUrl);
    return res.data;
  }
  catch (error) {
    return error;
  }
})

export const deletePersonalFileAction = createAsyncThunk('appChat/deletePersonalFile', async (payload: { fileIDs: string[], baseUrl: string }) => {
  try {
    const data = {
      fileIDs: payload.fileIDs
    }
    const res = await deletePersonalFile(data, payload.baseUrl);
    return res.data;
  }
  catch (error) {
    return error;
  }
})

export const setFeedbackAction = createAsyncThunk('appChat/setFeedback', async (payload: { chatID: string; messageID: number; evaluation: number; feedback: string, baseUrl: string }) => {
  try {
    const data = {
      chatID: payload.chatID,
      messageID: payload.messageID,
      evaluation: payload.evaluation,
      feedback: payload.feedback
    }
    const res = await setFeedback(data, payload.baseUrl);
    return res.data;
  }
  catch (error) {
    return error;
  }
})

const initialState: ChatState = {
  chatId: null,
  taskID: '',
  skillList: [],
  skillID: '',
  taskList: [],
  collectionList: [],
  modelID: "",
  historyList: [],
  messages: [],
  isNewChat: false,
  loadingAsk: false,
  chatController: undefined,
  currentCode: "",
  haveFile: false,
  uploading: false,
  files: [],
  promptValue: "",
  place: "message",
  description: "",
  skillInfo: null,
}

const chatSlice = createSlice({
  name: "chat",
  initialState,
  reducers: {
    setChatId(state, action) {
      state.chatId = action.payload;
    },
    addMessage(state, action) {
      state.messages.push(action.payload);
    },
    resetMessages(state) {
      state.messages = [];
    },
    setTaskID(state, action) {
      state.taskID = action.payload;
    },
    setSkillID(state, action) {
      state.skillID = action.payload;
    },
    setModelID(state, action) {
      state.modelID = action.payload;
    },
    setDescription(state, action) {
      state.description = action.payload;
    },
    setHistoryList(state, action) {
      state.historyList = action.payload;
    },
    setCollectionList(state, action) {
      state.collectionList = action.payload;
    },
    setIsNewChat(state, action) {
      state.isNewChat = action.payload;
    },
    setLoadingAsk(state, action) {
      state.loadingAsk = action.payload;
    },
    setBotResult(state, action) {
      const { result, source, chatID, done, id } = action.payload;
      const botMessage = state.messages.findIndex((item) => item.role === 'bot' && item.create_at === state.currentCode);
      if (botMessage !== -1) {
        if (result) state.messages[botMessage].content = result;
        if (source) state.messages[botMessage].source = source;
        if (done) state.messages[botMessage].done = done
        if (id) state.messages[botMessage].id = id
        state.messages[botMessage].chatID = chatID;
        if (state.skillID) {
          state.messages[botMessage].skillID = state.skillID;
        }
      }
    },
    setFeedbackStatus(state, action) {
      const { messageID, evaluation, feedback } = action.payload;
      const index = state.messages.findIndex((item) => item.id === messageID);
      if (index !== -1) {
        state.messages[index].evaluation = evaluation;
        state.messages[index].feedback = feedback
      }
    },
    setCurrentCode(state, action) {
      state.currentCode = action.payload;
    },
    setHaveFile(state, action) {
      state.haveFile = action.payload;
    },
    setUploading(state, action) {
      state.uploading = action.payload;
    },
    setFiles(state, action) {
      state.files = action.payload;
    },
    setPromptValue(state, action) {
      state.promptValue = action.payload;
    },
    setPlace(state, action) {
      state.place = action.payload;
    },
    setSkillInfo(state, action) {
      state.skillInfo = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(getSkillInfoAction.fulfilled, (state, action) => {
        const { data } = action.payload as { data: Skill };
        if (!data) return;
        state.modelID = data.modelName;
        state.description = data.description;
        state.skillInfo = data;
      })
      .addCase(uploadFileAction.pending, (state) => {
        state.uploading = true;
      })
      .addCase(uploadFileAction.fulfilled, (state, action) => {
        // state.uploading = false
        if (!action.payload.data) {
          state.uploading = false;
          return;
        }
        const { data: { chatID } } = action.payload
        if (chatID) {
          state.chatId = chatID
        }
      })
      .addCase(uploadFileAction.rejected, () => {
        // state.uploading = false;
      })
  }
});

export const {
  setChatId,
  addMessage,
  setHistoryList,
  resetMessages,
  setCollectionList,
  setTaskID,
  setSkillID,
  setIsNewChat,
  setLoadingAsk,
  setModelID,
  setDescription,
  setBotResult,
  setCurrentCode,
  setHaveFile,
  setUploading,
  setFiles,
  setFeedbackStatus,
  setPromptValue,
  setPlace
} = chatSlice.actions;
export default chatSlice.reducer;