import React, { useState, useRef, useMemo } from 'react';
import InputField from './InputField';
import { useDispatch, useSelector } from 'react-redux';
import { setFiles, setUploading, uploadFileAction } from '@/store/module/chat/chatSlice';
import { useParams } from 'react-router-dom';
import { RootState, AppDispatch } from '@/store';
import { toast } from '@/shadcn-ui/components/ui/use-toast';
import { useTranslation } from 'react-i18next';
import DorpNotice from './DorpNotice';

interface ChatWithDragDropProps {
  apiKey: string;
  baseUrl: string;
}

export default function ChatWithDragDrop({ apiKey, baseUrl }: ChatWithDragDropProps) {
  const [dragActive, setDragActive] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  // 從 redux 取得相關資料與 dispatch
  const dispatch = useDispatch<AppDispatch>();
  const { chatId } = useParams<{ chatId: string }>();
  const { files, skillList, taskID } = useSelector((state: RootState) => state.chat);
  const chat = useSelector((state: RootState) => state.chat);
  const { t: commonT } = useTranslation('common');

  // 用於延遲判斷 dragleave
  let dragLeaveTimeout: NodeJS.Timeout | null = null;

  const handleDropFiles = (dorpFiles: FileList) => {
    if (!dorpFiles) return
    if (!taskID) return
    const uploadFiles = Array.from(dorpFiles || [])
      .map(file => ({
        id: '',
        fileName: file.name,
        file: file
      }));

    const transformFiles = uploadFiles.map(file => file.file)

    dispatch(uploadFileAction({ files: transformFiles, chatID: chatId || chat.chatId || undefined, skillID: taskID, baseUrl: baseUrl }))
      .then((res) => {
        const { payload: { data } } = res
        const successFiles = uploadFiles.filter(item => {
          const correspondingFile = data.success.find((file: { id: string, name: string }) => file.name === item.fileName);
          if (correspondingFile) {
            const sameNameFile = files.find(file => file.fileName === item.fileName);
            const sameNameIndex = files.findIndex(file => file.fileName === item.fileName);
            if (sameNameFile) {
              dispatch(setFiles(
                [...files.slice(0, sameNameIndex), { ...sameNameFile, id: correspondingFile.id }, ...files.slice(sameNameIndex + 1)]
              ))
              return false;
            }

            // 如果找到對應的fileName，將id塞進去
            item.id = correspondingFile.id;

            return true;  // 保留符合條件的項目
          }
          return false;  // 如果沒有找到對應的id，則過濾掉這個項目
        });
        const failFiles = uploadFiles.filter(item => {
          const errorName = data.error.map((file: { name: string }) => file.name);

          return errorName.includes(item.fileName);
        })
        dispatch(setFiles([...files, ...successFiles]))
        dispatch(setUploading(false))

        if (failFiles.length > 0) {
          toast({
            title: commonT('uploadError'),
            description: (
              <ul className='list-decimal'>
                {failFiles.map((item, index) => (
                  <li key={index}>{item.fileName}</li>
                ))}
              </ul>
            ),
            variant: 'destructive',
            duration: 5000,
          })
        }
      })
      .catch(() => setFiles([...files]))
  };

  const skillName = useMemo(() => {
    if (!skillList || skillList.length === 0) return ''
    const skill = skillList.find(item => item.skillID === taskID)
    return skill?.skillName || 'none'
  }, [skillList, taskID]);

  const fileCanUpload = useMemo(() => {
    const skill = skillList.find(item => item.skillID === taskID)
    if (!skill) return false
    if (!skill.config) return false
    if (!skill.config.upload) return false
    return true
  }, [skillList, taskID])


  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
    if (!skillName || skillName === 'none' || !fileCanUpload) {
      return
    }

    e.preventDefault();
    // 若有延遲任務，清除它
    if (dragLeaveTimeout) {
      clearTimeout(dragLeaveTimeout);
      dragLeaveTimeout = null;
    }
    setDragActive(true);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    if (!skillName || skillName === 'none' || !fileCanUpload) {
      return
    }
    e.preventDefault();
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    // 設定一個短暫的延時，在延時後判斷是否真的離開區域
    dragLeaveTimeout = setTimeout(() => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX;
        const y = e.clientY;
        // 如果滑鼠位置超出容器範圍，才認定為離開
        if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
          setDragActive(false);
        }
      }
    }, 50);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    if (!skillName || skillName === 'none' || !fileCanUpload) {
      return
    }
    // 清除延時任務
    if (dragLeaveTimeout) {
      clearTimeout(dragLeaveTimeout);
      dragLeaveTimeout = null;
    }
    setDragActive(false);
    if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleDropFiles(e.dataTransfer.files);
      e.dataTransfer.clearData();
    }
  };

  return (
    <div
      ref={containerRef}
      onDragOver={handleDragOver}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`relative ${dragActive ? 'border-2 border-dashed rounded-lg' : ''}`}
    >
      {/* 這裡可以放入你原有的 InputField 組件 */}
      <DorpNotice className={`w-full h-full absolute bottom-0 z-50 pointer-events-none ${dragActive ? 'flex' : 'hidden'}`} />
      <InputField apiKey={apiKey} baseUrl={baseUrl} />
    </div>
  );
}
