import { Textarea } from "@/shadcn-ui/components/ui/textarea";
import UploadFiles from "../UploadModal";
import { Button } from "@/shadcn-ui/components/ui/button";
import { Paperclip, SendHorizontal, Mic } from "lucide-react";
import { PromptSelect } from "@/shadcn-ui/components/ui/prompt-select";
import { useTranslation } from "react-i18next";
import { useSelector, useDispatch } from "react-redux";
import { RootState, AppDispatch } from "@/store";
import { useMemo, useRef, useState } from "react";
import { addMessage, deletePersonalFileAction, setBotResult, setCurrentCode, setFiles, setLoadingAsk, setPromptValue, setUploading, uploadFileAction } from "@/store/module/chat/chatSlice";
import { postAsk } from "@/api/chatApi";
import { useScrollToBottom } from "react-scroll-to-bottom";
import { toast } from "@/shadcn-ui/components/ui/use-toast";
import SpeechModal from "../speechModal";

interface InputFieldProps {
  apiKey: string;
  baseUrl: string;
}

export default function InputField({ apiKey, baseUrl }: InputFieldProps) {
  const [value, setValue] = useState('')
  const { t } = useTranslation('chat')
  const { t: commonT } = useTranslation('common')
  const { skillInfo, modelID, promptValue, loadingAsk, uploading, taskID, files } = useSelector((state: RootState) => state.chat)
  const chat = useSelector((state: RootState) => state.chat)
  const scrollToBottom = useScrollToBottom();
  const dispatch: AppDispatch = useDispatch();

  const textAreaRegex = /^[\n\s]+$/;

  const isSendDisabled = useMemo(
    () => {
      const disabled = !value ? true :
        textAreaRegex.test(value) ? true : false
      return disabled
    }
    , [value])

  const handleKeyChange = (value: string) => {
    setValue(value)
  }

  const handleKeyDown = async (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault(); // 阻止換行
      await handleSend((event.currentTarget as HTMLInputElement).value)
    }
  };

  const handleSend = async (question: string) => {
    if (!question) return
    if (textAreaRegex.test(question)) return
    if (loadingAsk) return

    const message = { role: 'user', content: question, create_at: new Date().toISOString() }
    const data = {
      question,
      chatID: chat.chatId || null,
      apiKey: apiKey,
      userPrompt: promptValue
    }
    dispatch(addMessage(message))
    setValue('')

    dispatch(setLoadingAsk(true))
    const stream = postAsk(data, baseUrl)
    await stream({ onopen, onmessage, onerror })
    scrollToBottom();
    dispatch(setLoadingAsk(false))
  }

  const onopen = (response: Response) => {
    if (response.status === 200) {
      const currentTime = new Date().toISOString()
      dispatch(addMessage({
        role: 'bot',
        content: '',
        source: [],
        chatId: '',
        create_at: currentTime
      }))
      dispatch(setCurrentCode(currentTime))
    }
  }

  const onmessage = (data: any) => {
    const { chatID, result, source, done, messageID } = data
    dispatch(setBotResult({ chatID, result }))
    scrollToBottom();
    if (done) {
      dispatch(setBotResult({ chatID, source, done, id: messageID }))
    }
  }

  const onerror = (error: Error) => {
    dispatch(setLoadingAsk(false))
    toast({
      title: 'Error',
      description: error.message,
      variant: 'destructive',
      duration: 3000,
    })
  }

  const uploadRef = useRef<HTMLInputElement>(null);
  const openFileUpload = () => {
    uploadRef.current?.click();
  }

  const handleFiles = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return
    if (!taskID) return
    const uploadFiles = Array.from((e.target as HTMLInputElement).files || [])
      .map(file => ({
        id: '',
        fileName: file.name,
        file: file
      }));

    const transformFiles = uploadFiles.map(file => file.file)

    dispatch(uploadFileAction({ files: transformFiles, chatID: chat.chatId || undefined, skillID: taskID, baseUrl }))
      .then((res) => {
        const { payload: { data } } = res
        const successFiles = uploadFiles.filter(item => {
          const correspondingFile = data.success.find((file: { id: string, name: string }) => file.name === item.fileName);
          if (correspondingFile) {
            const sameNameFile = files.find(file => file.fileName === item.fileName);
            const sameNameIndex = files.findIndex(file => file.fileName === item.fileName);
            if (sameNameFile) {
              dispatch(setFiles(
                [...files.slice(0, sameNameIndex), { ...sameNameFile, id: correspondingFile.id }, ...files.slice(sameNameIndex + 1)]
              ))
              return false;
            }

            // 如果找到對應的fileName，將id塞進去
            item.id = correspondingFile.id;

            return true;  // 保留符合條件的項目
          }
          return false;  // 如果沒有找到對應的id，則過濾掉這個項目
        });
        const failFiles = uploadFiles.filter(item => {
          const errorName = data.error.map((file: { name: string }) => file.name);

          return errorName.includes(item.fileName);
        })
        dispatch(setFiles([...files, ...successFiles]))
        dispatch(setUploading(false))

        if (failFiles.length > 0) {
          toast({
            title: commonT('uploadError'),
            description: (
              <ul className='list-decimal'>
                {failFiles.map((item, index) => (
                  <li key={index}>{item.fileName}</li>
                ))}
              </ul>
            ),
            variant: 'destructive',
            duration: 5000,
          })
        }
      })
      .catch(() => setFiles([...files]))
    e.target.value = '';
  }

  const handlePaste = async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    if (!taskID) return
    if (!fileCanUpload) return
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {  // 判斷是否為圖片
        const fileData = items[i].getAsFile();
        const reader = new FileReader();
        reader.onload = (e) => {
          if (!fileData) return
          if (!e.target?.result) return
          const timestamp = new Date().getTime();
          const uploadFiles = [{
            id: '',
            fileName: fileData?.name + timestamp.toString() || timestamp.toString(),
            file: fileData
          }];
          const transformFiles = uploadFiles.map(file => {
            //檔案名稱要加上時間戳 記得要先把副檔名分開
            const fileName = file.fileName.split('.').slice(0, -1).join('.') + timestamp.toString() + '.' + file.file.name.split('.').pop();
            const renameFile = new File([file.file], fileName, { type: file.file.type });
            return renameFile;
          })
          dispatch(uploadFileAction({ files: transformFiles, chatID: chat.chatId || undefined, skillID: taskID, baseUrl }))
            .then((res) => {
              const { payload: { data } } = res
              const successFiles = uploadFiles.filter(item => {
                const correspondingFile = data.success.find((file: { id: string, name: string }) => file.name === item.fileName);
                if (correspondingFile) {
                  const sameNameFile = files.find(file => file.fileName === item.fileName);
                  const sameNameIndex = files.findIndex(file => file.fileName === item.fileName);
                  if (sameNameFile) {
                    dispatch(setFiles(
                      [...files.slice(0, sameNameIndex), { ...sameNameFile, id: correspondingFile.id }, ...files.slice(sameNameIndex + 1)]
                    ))
                    return false;
                  }

                  // 如果找到對應的fileName，將id塞進去
                  item.id = correspondingFile.id;

                  return true;  // 保留符合條件的項目
                }
                return false;  // 如果沒有找到對應的id，則過濾掉這個項目
              });
              const failFiles = uploadFiles.filter(item => {
                const errorName = data.error.map((file: { name: string }) => file.name);

                return errorName.includes(item.fileName);
              })
              dispatch(setFiles([...files, ...successFiles]))
              dispatch(setUploading(false))

              if (failFiles.length > 0) {
                toast({
                  title: commonT('uploadError'),
                  description: (
                    <ul className='list-decimal'>
                      {failFiles.map((item, index) => (
                        <li key={index}>{item.fileName}</li>
                      ))}
                    </ul>
                  ),
                  variant: 'destructive',
                  duration: 5000,
                })
              }
            })
            .catch(() => setFiles([...files]))

        };
        if (fileData) {
          reader.readAsDataURL(fileData);
        }
      }
    }
  };

  const deleteSingleFile = async (fileID: string, fileName: string) => {
    if (!chat.chatId) return
    const newFiles = files.filter(item => item.fileName !== fileName)
    await dispatch(deletePersonalFileAction({ fileIDs: [fileID], baseUrl }))
    dispatch(setFiles(newFiles))
  }

  const onPromptChange = (value: string) => {
    dispatch(setPromptValue(value));
  }

  const skillName = useMemo(() => {
    console.log('skillInfo', skillInfo)
    if (!skillInfo) return ''
    const skill = skillInfo
    return skill?.skillName || 'none'
  }, [skillInfo, taskID])

  const fileCanUpload = useMemo(() => {
    const skill = skillInfo
    if (!skill) return false
    if (!skill.config) return false
    if (!skill.config.upload) return false
    return true
  }, [skillInfo, taskID])

  const [speechOpen, setSpeechOpen] = useState(false)
  const handleSpeech = (transcript: string) => {
    setSpeechOpen(false)
    console.log(transcript)
    handleSend(transcript)
  }

  return (
    <>
      <div style={{ position: "relative" }}>
        <UploadFiles files={files} uploading={uploading} onRemove={deleteSingleFile} />
        <Textarea
          tabIndex={0}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck="false"
          placeholder={t('typeMessage')}
          aria-label="Ask anything. What are you stuck on?"
          style={{ resize: "none", height: "50px" }}
          disabled={loadingAsk || !skillName || skillName === 'none'}
          className='w-full border-0 rounded-tl-[0.5rem] rounded-br-[0.5rem] shadow-none bg-clip-border appearance-none bg-white searchbox-textarea text-base font-normal px-2 mx-0 row focus:outline-none'
          value={value}
          onKeyDown={handleKeyDown}
          onPaste={handlePaste}
          onChange={(e) => handleKeyChange(e.target.value)}
        />
      </div>
      <div
        // className="flex justify-between bg-[#DDE9FF]"
        className="flex px-1 justify-between"
      >
        {
          skillName === 'none' &&
          <div className="flex justify-end items-center gap-1 py-2 pl-2 text-red-500">
            {t("skillRemoved")}
          </div>
        }
        {skillName && skillName !== 'none' && <>
          <div className="flex justify-start items-center py-2">
            <div className='text-[#005e73] w-full flex items-center gap-1 rounded-xl py-1 pl-2 text-base font-bold whitespace-nowrap'>
              {skillName}
            </div>
            <div className='w-full flex items-center gap-1 rounded-xl py-1 px-2 text-base font-medium whitespace-nowrap'>
              {modelID}
            </div>
            <PromptSelect
              className='p-4 w-[250px] h-[250px]'
              // outsideClassName="h-8 px-1 py-0 gap-1 border-solid border rounded-sm h-full border-[#8FB7FF] text-[#8FB7FF] bg-[#DDE9FF] hover:bg-[#DDE9FF]/20"
              outsideClassName="h-8 px-1 py-0 gap-1 border-solid border rounded-sm h-full"
              value={promptValue}
              onChange={onPromptChange}
            />
          </div>
          <div className="flex justify-end items-center gap-1s">
            {fileCanUpload && <Button
              // className='w-8 h-8 border-0 flex items-center bg-[#DDE9FF] hover:bg-[#DDE9FF]/20'
              className='w-8 h-8 border-0 flex items-center'
              variant={'outline'}
              size={'icon'}
              disabled={loadingAsk || uploading}
              onClick={openFileUpload}
            >
              <Paperclip
                // color='#555a79' 
                size={18} />
              <input type="file" className='hidden' ref={uploadRef} multiple onChange={(e) => handleFiles(e)} />
            </Button>}
            <Button
              // className='w-8 h-8 border-0 flex items-center bg-[#DDE9FF] hover:bg-[#DDE9FF]/20'
              className='w-8 h-8 border-0 flex items-center'
              variant={'outline'}
              size={'icon'}
              disabled={loadingAsk || uploading}
              onClick={() => setSpeechOpen(true)}
            >
              <Mic
                // color='#555a79' 
                size={18} />
            </Button>
            <Button
              // className='w-8 h-8 border-0 flex items-center bg-[#DDE9FF] hover:bg-[#DDE9FF]/20'
              className='w-8 h-8 border-0 flex items-center'
              variant={'outline'}
              size={'icon'}
              disabled={isSendDisabled || loadingAsk || uploading}
              onClick={() => handleSend(value)}
            >
              <SendHorizontal
                // color='#555a79' 
                size={18} />
            </Button>
          </div>
        </>}
      </div>

      <SpeechModal isOpen={speechOpen} onClose={handleSpeech} />
    </>
  )
}