import * as React from 'react'
import { cn } from "@/shadcn-ui/lib/utils"

import { Bell, X } from "lucide-react"
import { Button } from "./button"
import {
  Popover,
  PopoverClose,
  PopoverContent,
  PopoverTrigger,
} from "./popover"
import { Textarea } from './textarea'
import { useTranslation } from 'react-i18next'


export type OptionType = {
  label: string;
  value: string;
  description?: string;
}

export type Tab = {
  label: string;
  value: string | number;
}

export type TabsType = Array<Tab>


interface PromptSelectProps {
  value?: string;
  clearable?: boolean;
  onChange?: (value: string) => void;
  className?: string;
  outsideClassName?: string;
  placeholder?: string;
  disabled?: boolean;
  nocancel?: boolean;
  search?: boolean;
}

function PromptSelect({
  value,
  onChange,
  clearable,
  className,
  outsideClassName,
  placeholder,
  nocancel,
  disabled,
  search,
  ...props
}: PromptSelectProps) {
  const [open, setOpen] = React.useState(false)
  const { t: prompT } = useTranslation('prompt')

  return (
    <Popover open={open} onOpenChange={setOpen} {...props}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn('w-full justify-between items-center py-1 px-2 relative group', outsideClassName)}
          disabled={disabled}
          onClick={() => setOpen(!open)}
        >
          {!value && <Bell size={18} />}
          <div className="hidden group-hover:block">
            <div
              className="group absolute rounded-md border bg-popover px-3 py-1.5 text-sm text-popover-foreground shadow-md animate-in fade-in-0 zoom-in-95 -top-12 left-1/2 z-50 flex -translate-x-1/2 flex-col items-center text-center"
            >
              <p className="whitespace-nowrap">
                {
                  !value ? prompT('prompt')
                    : prompT('customPrompt')
                }
              </p>
              {/* <div
                className="h-0 w-fit border-l-8 border-r-8 border-t-8 border-transparent border-t-black"
              ></div> */}
            </div>
          </div>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-full p-0" onPointerDownOutside={(e) => e.preventDefault()}>
        <div className={cn("p-4 flex gap-4 items-stretch flex-col md:flex-row", className)}>
          <Textarea
            className='w-full h-[300px] min-h-full resize-none overflow-y-auto grow md:grow-0'
            maxLength={5000}
            value={value}
            onChange={(e) => {
              onChange?.(e.target.value)
            }}
          />
        </div>
        <PopoverClose className='absolute top-2 right-2'>
          <X size={16} />
        </PopoverClose>
      </PopoverContent>
    </Popover >
  )
}

export { PromptSelect }