import { Button } from "@/shadcn-ui/components/ui/button"
import { useEffect, useState } from "react"
import { Badge } from "@/shadcn-ui/components/ui/badge"
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/shadcn-ui/components/ui/tooltip"
import ImageDialog from "@/shadcn-ui/components/ui/image-dialog"
import { Info } from "lucide-react"
import { useTranslation } from "react-i18next"

type Props = {
  files?: Files[]
  uploading?: boolean
  onRemove?: (fileID: string, fileName: string) => Promise<void>
}

export default function UploadFiles({ files = [], uploading, onRemove }: Props) {
  const { t } = useTranslation('common')
  const [show, setShow] = useState(files.length > 0)
  const [imageSrc, setImageSrc] = useState('')
  const [imageAlt, setImageAlt] = useState('')
  const [showImage, setShowImage] = useState(false)

  useEffect(() => {
    if (files.length === 0) {
      setShow(false)
    }

    if (uploading || files.length > 0) {
      setShow(true)
    }

  }, [files, uploading])

  //將檔案名稱中的附檔名去掉
  const removeExtension = (fileName: string) => {
    return fileName.replace(/\.[^/.]+$/, "")
  }

  //取得副檔名並大寫
  const getExtension = (fileName: string) => {
    return fileName.split('.').pop()?.toUpperCase()
  }

  //最多呈現20字元，超過則顯示...
  const truncate = (str: string, n: number) => {
    return (str.length > n) ? str.substr(0, n - 1) + '...' : str;
  }

  const deleteFile = async (fileID: string, fileName: string) => {
    await onRemove?.(fileID, fileName)
  }

  const isImageFile = (fileName: string) => {
    const ext = getExtension(fileName)
    return ['JPG', 'JPEG', 'PNG', 'GIF', 'BMP', 'WEBP', 'SVG'].includes(ext || '')
  }

  const openDialog = (file: Files) => {
    if (!isImageFile(file.fileName)) return
    if (!file.file) return
    setImageSrc(file.file)
    setImageAlt(file.fileName)
    setShowImage(true)
  }

  const closeDialog = () => {
    setShowImage(false)
  }

  return (
    <>
      <div className="relative">
        <div className={`w-full flex ${show ? 'h-full p-4' : 'h-0 p-0'} gap-2 flex-wrap items-center transition-all duration-300 ease-in-out`}>
          {show && files.map((file, index) => (
            <div key={index}>
              {/* <span>{file.name}</span> */}

              {!isImageFile(file.fileName) ?
                <div
                  className="relative flex flex-col gap-2 drop-shadow-xl w-32 h-24 border-solid border-gray-300 border whitespace-normal break-all rounded-xl bg-white"
                >
                  {file.has_image && <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <div className="absolute top-1 left-2 z-50">
                          <Info size={16} />
                        </div>
                      </TooltipTrigger>
                      <TooltipContent>
                        <div className="text-sm">{t("haveImage")}</div>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>}

                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <div
                          className="p-4 pt-5 text-sm font-bold flex items-center justify-center text-black z-[1] rounded-xl inset-0.5 bg-white"
                        >
                          <span>{truncate(removeExtension(file.fileName), 10)}</span>
                        </div>
                      </TooltipTrigger>
                      <TooltipContent>
                        <div className="text-sm">{removeExtension(file.fileName)}</div>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>

                  <div className="absolute mx-auto bottom-1 right-1/2 translate-x-1/2 translate-y-1/2">
                    <Badge>
                      {getExtension(file.fileName)}
                    </Badge>
                  </div>
                  {
                    //懸浮在右上角的刪除按鈕
                    <Button
                      variant={'link'}
                      className="absolute p-0 text-red-300 hover:text-red-500 top-0 right-0 translate-x-2 -translate-y-4 z-10"
                      onClick={() => {
                        deleteFile(file.id, file.fileName)
                      }}
                    >
                      <svg className="w-6 h-6 fill-current"
                        height="100"
                        preserveAspectRatio="xMidYMid meet"
                        viewBox="0 0 100 100"
                        width="100"
                        x="0"
                        xmlns="http://www.w3.org/2000/svg"
                        y="0">
                        <path
                          d="M50,87.4A37.4,37.4,0,1,0,12.6,50,37.3,37.3,0,0,0,50,87.4ZM44,37.3A4.7,4.7,0,0,0,37.3,44l6.1,6-6.1,6A4.7,4.7,0,0,0,44,62.7l6-6.1,6,6.1A4.7,4.7,0,0,0,62.7,56l-6.1-6,6.1-6A4.7,4.7,0,0,0,56,37.3l-6,6.1Z"
                          fillRule="evenodd"
                        >
                        </path>
                      </svg>

                    </Button>
                  }
                </div>
                :
                <div
                  className="relative flex flex-col gap-2 drop-shadow-xl w-32 h-24 border-solid border-gray-300 border whitespace-normal break-all rounded-xl bg-white"
                >
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <img
                          src={`${file.file}`}
                          alt={file.fileName}
                          className="w-full h-full object-cover rounded-xl"
                          onClick={() => openDialog(file)}
                        />
                      </TooltipTrigger>
                      <TooltipContent>
                        <div className="text-sm">{removeExtension(file.fileName)}</div>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                  {
                    //懸浮在右上角的刪除按鈕
                    <Button
                      variant={'link'}
                      className="absolute p-0 text-red-300 hover:text-red-500 top-0 right-0 translate-x-2 -translate-y-4 z-10"
                      onClick={() => {
                        deleteFile(file.id, file.fileName)
                      }}
                    >
                      <svg className="w-6 h-6 fill-current"
                        height="100"
                        preserveAspectRatio="xMidYMid meet"
                        viewBox="0 0 100 100"
                        width="100"
                        x="0"
                        xmlns="http://www.w3.org/2000/svg"
                        y="0">
                        <path
                          d="M50,87.4A37.4,37.4,0,1,0,12.6,50,37.3,37.3,0,0,0,50,87.4ZM44,37.3A4.7,4.7,0,0,0,37.3,44l6.1,6-6.1,6A4.7,4.7,0,0,0,44,62.7l6-6.1,6,6.1A4.7,4.7,0,0,0,62.7,56l-6.1-6,6.1-6A4.7,4.7,0,0,0,56,37.3l-6,6.1Z"
                          fillRule="evenodd"
                        >
                        </path>
                      </svg>

                    </Button>
                  }
                </div>
              }
            </div>
          ))}

          {
            uploading && show &&
            <div className="relative gap-2 drop-shadow-xl w-32 h-24 border-solid border-gray-300 border whitespace-normal break-all rounded-xl bg-white">
              <div className="shadow-super-inner w-full h-full rounded-xl flex items-center justify-center">
                <div className="flex-col gap-4 w-full flex items-center justify-center">
                  <div className="w-8 h-8 border-4 text-gray-700 text-4xl animate-spin border-gray-300 flex items-center justify-center border-t-gray-800 rounded-full">
                  </div>
                </div>
              </div>
            </div>
          }
        </div>

        {(uploading || files.length > 0) && < Button variant={'link'} className={`absolute right-0 ${show ? 'top-2' : 'top-0'}`} disabled={false} onClick={() => setShow(!show)}>
          {show && <svg width="20" height="20" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M7.5 2C7.77614 2 8 2.22386 8 2.5L8 11.2929L11.1464 8.14645C11.3417 7.95118 11.6583 7.95118 11.8536 8.14645C12.0488 8.34171 12.0488 8.65829 11.8536 8.85355L7.85355 12.8536C7.75979 12.9473 7.63261 13 7.5 13C7.36739 13 7.24021 12.9473 7.14645 12.8536L3.14645 8.85355C2.95118 8.65829 2.95118 8.34171 3.14645 8.14645C3.34171 7.95118 3.65829 7.95118 3.85355 8.14645L7 11.2929L7 2.5C7 2.22386 7.22386 2 7.5 2Z"
              fill="currentColor"
              fillRule="evenodd"
              clipRule="evenodd"
            />
          </svg>}
          {!show &&
            <svg width="20" height="20" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M7.14645 2.14645C7.34171 1.95118 7.65829 1.95118 7.85355 2.14645L11.8536 6.14645C12.0488 6.34171 12.0488 6.65829 11.8536 6.85355C11.6583 7.04882 11.3417 7.04882 11.1464 6.85355L8 3.70711L8 12.5C8 12.7761 7.77614 13 7.5 13C7.22386 13 7 12.7761 7 12.5L7 3.70711L3.85355 6.85355C3.65829 7.04882 3.34171 7.04882 3.14645 6.85355C2.95118 6.65829 2.95118 6.34171 3.14645 6.14645L7.14645 2.14645Z"
                fill="currentColor"
                fillRule="evenodd"
                clipRule="evenodd"
              />
            </svg>
          }
        </Button>}
      </div >

      <ImageDialog src={`${imageSrc}`} alt={imageAlt} open={showImage} onClose={closeDialog} />
    </>
  )
}