import { fetchEventSource } from '@microsoft/fetch-event-source'

interface EventStreamOptions {
  baseUrl: string
  method?: string
  headers?: Record<string, string> | undefined
  data?: BodyInit
  abortController?: AbortController
  openWhenHidden?: boolean
}

interface StreamEvent {
  onopen?: (response: Response) => void,
  onmessage?: (data: any) => void,
  onerror?: (error: Error) => void,
  onclose?: () => void
}

export default function eventStream(url: string, { baseUrl, method, headers, data, abortController, openWhenHidden = true }: EventStreamOptions) {
  url = baseUrl + url

  return async function ({ onopen, onmessage, onerror, onclose }: StreamEvent) {
    try {
      await fetchEventSource(url, {
        method,
        headers,
        body: data,
        signal: abortController?.signal,
        openWhenHidden,
        async onopen(response) {

          if (!response.ok) {
            const errorData = await response.text();
            const { msg } = JSON.parse(errorData)
            const error = new Error(msg);
            (error as any).data = errorData;
            onerror?.(error);

            throw error;
          }

          onopen?.(response);

          return undefined;
        },
        onmessage: (msg) => {
          try {
            const data = JSON.parse(msg.data);
            onmessage?.(data);

            const { done } = data;
            if (done || msg.event === 'close') {
              abortController?.abort();
            }
          } catch (err) {
            onerror?.(err as Error);
          }
        },
        onerror: (err) => {
          onerror?.(err);
          throw err;
        },
        onclose: () => {
          onclose?.();
          abortController?.abort();
        },
      });
    } catch (error) {
      // 捕獲所有錯誤並調用 onerror 回調
      onerror?.(error instanceof Error ? error : new Error('Unknown error occurred'));
      throw error; // 向上拋出錯誤，終止 eventStream
    }
  }
}